        static readonly string[] Codes = { "fr", "en", "es", "de" };
        public static readonly string Lang = Array.IndexOf(Codes, CultureInfo.CurrentUICulture.TwoLetterISOLanguageName) >= 0
            ? CultureInfo.CurrentUICulture.TwoLetterISOLanguageName : "en";
        static readonly int I = Array.IndexOf(Codes, Lang);

        public static string T(string key, params object[] a)
        {
            if (!S.TryGetValue(key, out var row)) return key;
            return a.Length == 0 ? row[I] : string.Format(row[I], a);
        }

        /// <summary>A label of the debug window's columns, padded to the column width (always one space after it).</summary>
        public static string Col(string key, int width) => T(key).PadRight(width - 1) + " ";

